// Static preview of public/ with a fake leaderboard, plus a measuring script injected into the page.
const http = require("http");
const fs = require("fs");
const path = require("path");
const root = process.argv[2];
const port = Number(process.argv[3] || 3123);
const types = { ".html": "text/html", ".css": "text/css", ".js": "text/javascript", ".svg": "image/svg+xml", ".png": "image/png", ".json": "application/json" };
const board = [
  { username: "Captain Coral", total_score: 1500, badges: ["easy", "medium", "hard"] },
  { username: "Bartholomew Fitzgerald-Long", total_score: 1400, badges: ["easy", "medium", "hard"] },
  { username: "Abby", total_score: 1300, badges: ["easy", "medium", "hard"] },
  { username: "Sam", total_score: 900, badges: ["easy", "medium"] },
  { username: "Jordan Q", total_score: 800, badges: ["easy", "hard"] },
  { username: "Riley", total_score: 500, badges: ["easy"] },
  { username: "Taylor", total_score: 400, badges: ["easy"] },
  { username: "Morgan", total_score: 300, badges: [] },
  { username: "Casey", total_score: 200, badges: [] },
];
const measure = `<script>
setTimeout(() => {
  const r = (s) => { const e = document.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect();
    return { top: Math.round(b.top), left: Math.round(b.left), width: Math.round(b.width), height: Math.round(b.height) }; };
  const rows = [...document.querySelectorAll("#start-screen .lb-row")].map((li) => {
    const n = li.querySelector(".lb-name").getBoundingClientRect(), s = li.querySelector(".lb-score").getBoundingClientRect();
    return { sameLine: Math.abs(n.top - s.top) < 6, scoreRight: Math.round(s.right), h: Math.round(li.getBoundingClientRect().height) };
  });
  const out = { vw: innerWidth, board: r(".home-board"), center: r(".home-center"), masters: r(".home-masters"),
    boardRows: document.querySelectorAll(".home-board .lb-row").length, rows };
  const pre = document.createElement("pre"); pre.id = "measure"; pre.textContent = JSON.stringify(out); document.body.appendChild(pre);
}, 1500);
</script>`;
http.createServer((req, res) => {
  const url = req.url.split("?")[0];
  if (url === "/api/leaderboard") { res.writeHead(200, { "Content-Type": "application/json" }); return res.end(JSON.stringify(board)); }
  const file = path.join(root, url === "/" ? "index.html" : url);
  if (!file.startsWith(root) || !fs.existsSync(file)) { res.writeHead(404); return res.end(); }
  let body = fs.readFileSync(file);
  if (file.endsWith("index.html") && process.argv[4] === "measure") body = body.toString().replace("</body>", measure + "</body>");
  res.writeHead(200, { "Content-Type": types[path.extname(file)] || "application/octet-stream" });
  res.end(body);
}).listen(port, () => console.log("preview on " + port));

